namespace ghidra.app.plugin.core.debug.gui.tracermi.launcher;







using org.junit;

using ghidra.app.plugin.core.terminal;
using ghidra.debug.api;
using ghidra.debug.api.tracermi;
using ghidra.framework.plugintool.AutoConfigState;
using ghidra.test;
using help.screenshot;

// Class name must be <topic>ScreenShots, and topic is "gdb", so yeah, lowercase!
public class gdbScreenShots : GhidraScreenShotGenerator {
	TraceRmiLauncherServicePlugin servicePlugin;

	protected void captureLauncherByTitle(string title, Map<string, ValStr<object>> args)
    {
		servicePlugin = addPlugin(tool, typeof(TraceRmiLauncherServicePlugin));

		ToyProgramBuilder pb = new ToyProgramBuilder("demo", false);

		TraceRmiLaunchOffer offer = servicePlugin.getOffers(pb.getProgram())
				.stream()
				.filter(o => title.equals(o.getTitle()))
				.findAny()
				.orElseThrow();

		AbstractTraceRmiLaunchOffer aoff = (AbstractTraceRmiLaunchOffer) offer;
		aoff.saveLauncherArgs(args, aoff.getParameters());

		runSwingLater(() => servicePlugin.configureAndLaunch(offer));

		TraceRmiLaunchDialog dialog = waitForDialogComponent(typeof(TraceRmiLaunchDialog));
		Window window = SwingUtilities.windowForComponent(dialog.getComponent());
		window.requestFocus();
		captureDialog(dialog);
	}

	protected ValStr<PathIsFile> fileArg(string path) {
		return new(new PathIsFile(Paths.get(path)), path);
	}

	/* @Test */
	public void testCaptureGdbLauncher()
    {
		captureLauncherByTitle("gdb", Map.of("arg:1", fileArg("/home/user/demo")));
	}

	/* @Test */
	public void testCaptureGdbTerminal()
    {
		servicePlugin = addPlugin(tool, typeof(TraceRmiLauncherServicePlugin));

		TraceRmiLaunchOffer offer = servicePlugin.getOffers(null)
				.stream()
				.filter(o => "gdb".equals(o.getTitle()))
				.findAny()
				.orElseThrow();

		servicePlugin.relaunch(offer);

		captureIsolatedProvider(typeof(TerminalProvider), 600, 600);
	}
}
